let response = "";
let model = $('Edit Fields').first().json.model;
if(model == 'gemini'){
  response = $input.first().json.candidates[0].content.parts[0].text
}else if(model == 'chatgpt'){
  let rawResponse = JSON.parse($input.first().json.data);
  response = rawResponse.choices[0].message.content
}else if(model == 'claude'){
  let rawResponse = JSON.parse($input.first().json.data);
  response = rawResponse.content[0].text;
}else if(model == 'grok'){
  function cleanupMarkdownHtml(markdownText) {
  // Matches ```html (case-insensitive) at the start and ``` at the end, 
  // removing them while capturing everything inside.
    return markdownText.replace(/^```html\s*([\s\S]*?)\s*```$/i, '$1').trim();
  }
  response = cleanupMarkdownHtml($input.first().json.output[0].content[0].text);
}
let data = {
  response: response,
  competitors: $('Model Looping').first().json.competitors,
  company: $('Model Looping').first().json.company,
  brand: $('Model Looping').first().json.brand,
  industry: $('Model Looping').first().json.industry,
  tone_of_voice: $('Model Looping').first().json.tone_of_voice,
  description: $('Model Looping').first().json.description,
  key_features: $('Model Looping').first().json.key_features,
  persona: $('Model Looping').first().json.persona
}

return {
  json: data
}

let payload;
let model = $input.first().json.model;
if(model === 'gemini'){
  payload =  {
        "url": "https://api.kie.ai/gemini/v1/models/gemini-3-5-flash:streamGenerateContent",
        "config": {
             "stream": false,
             "contents": [
                {
                   "role": "user",
                   "parts": [
                      {
                         "text": $input.first().json.prompt
                      }
                   ]
                },
               {
                   "role": "user",
                   "parts": [
                      {
                         "text": $input.first().json.instruction
                      }
                   ]
                }
             ],
             "tools": [
                {
                   "googleSearch": {}
                }
             ],
             "generationConfig": {
                "thinkingConfig": {
                   "includeThoughts": false,
                   "thinkingLevel": "high"
                }
             }
        }
  }
}else if(model === 'chatgpt'){
  payload =  {
        "url": "https://api.kie.ai/gpt-5-2/v1/chat/completions",
        "config": {
                "messages": [
                   {
                      "role": "user",
                      "content": [
                         {
                            "type": "text",
                            "text": $input.first().json.prompt
                         }
                      ]
                   },
                   {
                      "role": "user",
                      "content": [
                         {
                            "type": "text",
                            "text": $input.first().json.instruction
                         }
                      ]
                   }
                ],
                "tools": [
                   {
                      "type": "function",
                      "function": {
                         "name": "web_search"
                      }
                   }
                ],
                "reasoning_effort": "high"
        }
  }
}else if(model === 'claude'){
  payload =  {
        "url": "https://api.kie.ai/claude/v1/messages",
        "config": {
                "model": "claude-haiku-4-5",
                "messages": [
                   {
                      "role": "user",
                      "content":  $input.first().json.prompt
                   },
                   {
                      "role": "user",
                      "content":  $input.first().json.instruction
                   }
                ],
                "tools": [],
                "thinkingFlag": true,
                "stream": false,
                "max_tokens": 4096
             }
  }

}else if(model === 'grok'){
  payload =  {
        "url": "https://api.kie.ai/grok/v1/responses",
        "config":{
                "model": "grok-4-3",
                "stream": false,
                "input": [
                   {
                      "role": "user",
                      "content": [
                         {
                            "type": "input_text",
                            "text": $input.first().json.prompt
                         }
                      ]
                   },
                   {
                      "role": "user",
                      "content": [
                         {
                            "type": "input_text",
                            "text": $input.first().json.instruction
                         }
                      ]
                   }
                ],
               "tools": [
                        {
                          "type": "web_search"
                        }
                ]
        }
  }
}

return payload;
